head.script:
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)

// 2010.06.25  전부보유리스트 조치_STF35500 변경에 따라 자전거래 항목 삭제

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        const parentWin = $c.frame.path("../");
        txb_ISU_CD.setValue(parentWin.clickIsuCd);
        txb_ISU_NM.setValue(parentWin.clickIsuKorAbbrv);
        const vCurDate = $c.ut.cGetToday("yyyymmdd");
        edt_START_DD.setValue($c.ut.cGetMinusDate2(vCurDate, 30));
        edt_END_DD.setValue(vCurDate);
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35503.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35503.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_ELW_HD_DTL_OnLoadError
 * @description dts_ELW_HD_DTL 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ELW_HD_DTL_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_ELW_HD_DTL);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35503.dts_ELW_HD_DTL_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_ELW_HD_DTL_OnLoadCompleted
 * @description dts_ELW_HD_DTL 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ELW_HD_DTL_OnLoadCompleted = function(rowcount) {
    try {
        edt_TotalCnt.setValue("총 " + dts_ELW_HD_DTL.getRowCount() + "건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35503.dts_ELW_HD_DTL_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35503.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name img_START_DD_onclick
 * @description img_START_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_START_DD_onclick = function() {
    try {
        popUpCalendar2(edt_START_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35503.img_START_DD_onclick" });
    }
};

/**
 * @method
 * @name img_END_DD_onclick
 * @description img_END_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_END_DD_onclick = function() {
    try {
        popUpCalendar2(edt_END_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35503.img_END_DD_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    if (parseInt(edt_START_DD.getValue(), '10') > parseInt(edt_END_DD.getValue(), '10')) {
        await $c.win.alert("[시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        return;
    }
    url += "&ISU_CD=" + txb_ISU_CD.getValue();
    url += "&SDATE=" + edt_START_DD.getValue();
    url += "&EDATE=" + edt_END_DD.getValue();
    const sbmOptions = {
        id : "sbm_dts_ELW_HD_DTL",
        action : "/ELWAllHoldAction.do",
        ref : "",
        target : "dts_ELW_HD_DTL=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
